package com.byawasaya.platform.auth;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service public class LoginRateLimitService {
 private final JdbcTemplate jdbc; public LoginRateLimitService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public void check(String identifier,String ip){String key=key(identifier,ip);var rows=jdbc.query("SELECT locked_until FROM login_attempts WHERE key_hash=?",(rs,n)->rs.getObject(1),key);if(!rows.isEmpty()&&rows.get(0)!=null){Object value=rows.get(0);java.time.Instant until=value instanceof java.time.OffsetDateTime o?o.toInstant():value instanceof java.sql.Timestamp t?t.toInstant():null;if(until!=null&&until.isAfter(java.time.Instant.now()))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many sign-in attempts. Try again later.");}}
 @Transactional public void failure(String identifier,String ip){String k=key(identifier,ip);jdbc.update("INSERT INTO login_attempts(key_hash,failures,window_started_at,locked_until,updated_at) VALUES(?,1,now(),NULL,now()) ON CONFLICT(key_hash) DO UPDATE SET failures=CASE WHEN login_attempts.window_started_at < now()-interval '15 minutes' THEN 1 ELSE login_attempts.failures+1 END,window_started_at=CASE WHEN login_attempts.window_started_at < now()-interval '15 minutes' THEN now() ELSE login_attempts.window_started_at END,locked_until=CASE WHEN (CASE WHEN login_attempts.window_started_at < now()-interval '15 minutes' THEN 1 ELSE login_attempts.failures+1 END)>=5 THEN now()+interval '15 minutes' ELSE login_attempts.locked_until END,updated_at=now()",k);}
 @Transactional public void success(String identifier,String ip){jdbc.update("DELETE FROM login_attempts WHERE key_hash=?",key(identifier,ip));}
 private String key(String identifier,String ip){return hash((identifier==null?"":identifier.trim().toLowerCase())+"|"+(ip==null?"unknown":ip));}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
